import base64, time, jwt

from uuid import uuid4

from cryptography.hazmat.primitives.asymmetric import rsa

from fastapi import FastAPI

from pydantic import BaseModel



app = FastAPI(title="auth-service")

ISSUER = "http://auth-service:9000"

AUDIENCE = "payments-api"

KID = "local-dev-key"



def b64u(n: int) -> str:

    raw = n.to_bytes((n.bit_length() + 7) // 8, "big")

    return base64.urlsafe_b64encode(raw).rstrip(b"=").decode()



@app.on_event("startup")

async def startup():

    key = rsa.generate_private_key(public_exponent=65537, key_size=2048)

    pub = key.public_key().public_numbers()

    app.state.key = key

    app.state.jwks = {"keys":[{"kty":"RSA","use":"sig","alg":"RS256","kid":KID,"n":b64u(pub.n),"e":b64u(pub.e)}]}



class TokenRequest(BaseModel):

    sub: str

    email: str

    roles: list[str] = ["customer"]

    scopes: list[str] = []



@app.get("/health")

async def health(): return {"status":"ok"}



@app.get("/.well-known/jwks.json")

async def jwks(): return app.state.jwks



@app.post("/token")

async def token(payload: TokenRequest):

    now = int(time.time())

    encoded = jwt.encode(

        {
            "sub": payload.sub,
            "email": payload.email,
            "roles": payload.roles,
            "scopes": payload.scopes,
            "iss": ISSUER,
            "aud": AUDIENCE,
            "iat": now,
            "exp": now + 3600,
            "jti": str(uuid4()),
        },
        app.state.key,
        algorithm="RS256",
        headers={"kid": KID},
    )

    return {"access_token": encoded, "token_type": "bearer"}
